begin;
do $$declare tid uuid;other uuid;a uuid;b uuid;c uuid;cid uuid:=gen_random_uuid();plain uuid:=gen_random_uuid();file_path text;foreign_path text;r jsonb;before_payment jsonb;begin
 select owner_id into a from public.trips where name='ทดสอบ'limit 1;select id into b from public.profiles where id<>a limit 1;select id into c from public.profiles where id not in(a,b)limit 1;
 insert into public.trips(name,owner_id,start_date,end_date,status)values('QA financial integrity rollback',a,current_date,current_date+1,'planning')returning id into tid;
 insert into public.trip_members(trip_id,user_id,trip_role,can_manage_fund,can_confirm_payments)values(tid,a,'owner',true,true),(tid,b,'member',false,true),(tid,c,'member',false,false);
 insert into public.trips(name,owner_id,start_date,end_date,status)values('QA foreign file rollback',b,current_date,current_date+1,'planning')returning id into other;insert into public.trip_members(trip_id,user_id,trip_role)values(other,b,'owner');
 file_path:=tid||'/'||c||'/qa-slip.png';foreign_path:=other||'/'||b||'/foreign-slip.png';
 insert into storage.objects(bucket_id,name,owner_id)values('trip-files',file_path,c::text),('trip-files',foreign_path,b::text),('trip-files',tid||'/'||a||'/qr.png',a::text);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 update public.profiles set account_name='QA account',payment_qr_path=tid||'/'||a||'/qr.png'where id=a;
 perform public.trip_fund_action(tid,'contribution',jsonb_build_object('collection_id',cid,'title','QA contribution','custodian_id',a,'amounts',jsonb_build_object(c,10000)),gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 perform public.submit_collection_payment(cid,file_path,c);
 if public.trip_fund_balance(tid)<>0 then raise exception 'Pending became cash';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform public.confirm_collection_received(cid,c,100);perform public.confirm_collection_received(cid,c,100);
 if public.trip_fund_balance(tid)<>10000 or(select count(*) from public.trip_fund_transactions where collection_id=cid and type='deposit')<>1 then raise exception 'Confirmer-only permission or duplicate credit failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.save_collection_request(tid,plain,jsonb_build_object('title','QA plain history','receiver_id',a,'amounts',jsonb_build_object(c,10000)));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 begin perform public.submit_collection_payment(plain,foreign_path,c);raise exception 'Cross-trip slip accepted';exception when insufficient_privilege then null;end;
 perform public.submit_collection_payment(plain,file_path,c);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 begin perform public.submit_collection_payment(plain,foreign_path,c);raise exception 'Pending overwritten by other member';exception when insufficient_privilege then null;end;
 perform public.confirm_collection_received(plain,c,100);
 select to_jsonb(p)into before_payment from public.collection_payments p where collection_id=plain and user_id=c;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 perform public.submit_collection_payment(plain,file_path,c);
 if(select to_jsonb(p)from public.collection_payments p where collection_id=plain and user_id=c)<>before_payment then raise exception 'Confirmed retry altered history';end if;
 begin perform public.submit_collection_payment(plain,foreign_path,c);raise exception 'Confirmed receipt overwritten';exception when raise_exception then if sqlerrm='Confirmed receipt overwritten'then raise;end if;end;
 if not public.trip_financial_file_locked(file_path)then raise exception 'Confirmed file not protected';end if;
 if public.trip_file_folder_readable(foreign_path)then raise exception 'Foreign folder readable';end if;
 begin insert into public.expenses(trip_id,title,amount,paid_by,created_by,approval_status,receipt_path)values(tid,'QA forbidden expense file',10,c,c,'pending',foreign_path);raise exception 'Expense cross-trip attachment accepted';exception when insufficient_privilege then null;end;
 perform set_config('qa.integrity.trip',tid::text,true);perform set_config('qa.integrity.other',other::text,true);perform set_config('qa.integrity.file',file_path,true);perform set_config('qa.integrity.foreign',foreign_path,true);perform set_config('qa.integrity.user',c::text,true);
end$$;
set local role authenticated;
do $$declare n integer;begin
 select count(*)into n from storage.objects where bucket_id='trip-files'and name=current_setting('qa.integrity.foreign');if n<>0 then raise exception 'Foreign storage row exposed';end if;
 begin update storage.objects set metadata=coalesce(metadata,'{}')||'{"qa":true}'where bucket_id='trip-files'and name=current_setting('qa.integrity.file');get diagnostics n=row_count;if n<>0 then raise exception 'Referenced slip overwritten';end if;exception when insufficient_privilege then null;end;
 begin delete from storage.objects where bucket_id='trip-files'and name=current_setting('qa.integrity.file');get diagnostics n=row_count;if n<>0 then raise exception 'Referenced slip deleted';end if;exception when insufficient_privilege then null;end;
end$$;
reset role;
rollback;
